export const VAULT = {"salt":"YhOEzm10VQs9Pz72nAVc1Q==","iv":"h6XtqWMtj+pfJ5R3","ct":""};

export async function unseal(key) {
  const b = (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0));
  const base = await crypto.subtle.importKey('raw', new TextEncoder().encode(key), 'PBKDF2', false, ['deriveKey']);
  const aes = await crypto.subtle.deriveKey(
    { name: 'PBKDF2', hash: 'SHA-256', salt: b(VAULT.salt), iterations: 600000 },
    base,
    { name: 'AES-GCM', length: 256 },
    false,
    ['decrypt'],
  );
  const plain = await crypto.subtle.decrypt({ name: 'AES-GCM', iv: b(VAULT.iv) }, aes, b(VAULT.ct));
  return new TextDecoder().decode(plain);
}
